const $=id=>document.getElementById(id), colors=['#0eaa91','#5890b0','#b4986d','#9b84ad','#8aa664','#cf8c7c','#57a2a5'];
let run=null,rows=[],view='separation',selected='all',chartPoints=[],feedBase='data/';
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,d=2)=>v==null||!Number.isFinite(v)?'—':v.toFixed(d);
function toast(message){$('toast').textContent=message;$('toast').hidden=false;setTimeout(()=>$('toast').hidden=true,6000)}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function showDialog(title,body){$('dialog-title').textContent=title;$('dialog-body').textContent=typeof body==='string'?body:JSON.stringify(body,null,2);$('dialog').showModal()}
function status(s){const reasons=(s.reasons||[]).filter(x=>!['gp_set_change','ephemeris_change','rms_threshold','maximum_threshold'].includes(x));const t=run.config.thresholds[s.orbit_class];return !s.valid_epochs||s.valid_epochs<s.total_epochs||reasons.length||s.rms_km>t.rms_km||s.max_km>t.max_km?'Review':'Close'}
function load(summary,epochs){if(summary.schema_version!=='1.0.0'||!Array.isArray(summary.satellites)||!summary.config?.thresholds||!Array.isArray(epochs))throw Error('Expected a pipeline v1.0.0 summary.json and epochs.json.');const ids=new Set(summary.satellites.map(s=>s.prn));if(ids.size!==summary.satellites.length||epochs.some(r=>!ids.has(r.prn)))throw Error('Satellite registry and epochs do not agree.');for(const s of summary.satellites){if(!summary.config.thresholds[s.orbit_class])throw Error('Missing orbit-class thresholds.');const n=epochs.filter(r=>r.prn===s.prn&&r.separation_km!==null).length;if(n!==s.valid_epochs)throw Error('Summary and epoch coverage do not agree.');}run=summary;rows=epochs;selected='all';$('satellite').innerHTML='<option value="all">All satellites</option>'+run.satellites.map(s=>`<option value="${escapeHTML(s.prn)}">${escapeHTML(s.prn)} · ${escapeHTML(s.name)}</option>`).join('');$('day-label').textContent=run.day;$('run-state').classList.add('loaded');$('run-state').replaceChildren(document.createTextNode('OBSERVED RUN / PRELIMINARY'));const state=document.createElement('span');state.textContent=`${rows.length.toLocaleString()} satellite-epochs · ${run.config.step_seconds} s grid · thresholds ${run.config.threshold_calibration}`;$('run-state').append(state);const compared=run.satellites.filter(s=>s.valid_epochs>0),rms=compared.reduce((n,s)=>n+s.rms_km,0)/compared.length,worst=[...compared].sort((a,b)=>b.rms_km-a.rms_km)[0];$('count').innerHTML=`${compared.length}<small>/ ${run.satellites.length} present</small>`;$('count-note').textContent=`${rows.filter(r=>r.separation_km!==null).length.toLocaleString()} valid paired epochs`;$('rms').innerHTML=`${fmt(rms)}<small>km</small>`;$('worst').textContent=worst?.prn||'—';$('worst-note').textContent=worst?`${fmt(worst.rms_km)} km RMS · ${worst.orbit_class}`:'No paired residuals available';$('reviews').textContent=run.satellites.filter(s=>status(s)==='Review').length;$('review-note').textContent='Computed from limits and quality flags';$('run-id').textContent=run.run_id;$('table-count').textContent=run.satellites.length;$('export').disabled=false;$('manifest').disabled=false;$('report-link').href='data/report.md';$('report-link').onclick=e=>{e.preventDefault();fetch(feedBase+'report.md').then(r=>{if(!r.ok)throw Error('Unavailable');return r.text()}).then(t=>showDialog('Technical report',t)).catch(()=>showDialog('Method & limitations',run.notes.join('\n\n')+'\n\nGenerate report.md using the Python pipeline.'))};$('chart-note').textContent=`${run.config.step_seconds}-second grid · shared UTC epochs · no extrapolation`;renderTable();renderQuality();renderChart();renderGenerator()}
function renderTable(){if(!run)return;const filter=$('status-filter').value;const sats=run.satellites.filter(s=>filter==='all'||status(s)===filter);$('satellite-rows').innerHTML=sats.length?sats.map(s=>`<tr class="clickable" tabindex="0" data-prn="${escapeHTML(s.prn)}" aria-label="Inspect ${escapeHTML(s.prn)}"><td><div class="sat-name"><span class="sat-icon">${escapeHTML(s.prn.slice(1))}</span><div><strong>${escapeHTML(s.prn)} · ${escapeHTML(s.name)}</strong><small>NORAD ${escapeHTML(s.norad_id||'unconfirmed')}</small></div></div></td><td><span class="orbit-badge">${escapeHTML(s.orbit_class)}</span></td><td class="number">${fmt(s.rms_km)}</td><td class="number">${fmt(s.max_km)}</td><td class="number">${fmt(s.coverage_percent,1)}%</td><td><span class="status ${status(s).toLowerCase()}">● ${status(s)}</span></td></tr>`).join(''):'<tr><td colspan="6" class="empty-row">No satellites match this filter.</td></tr>';document.querySelectorAll('tr[data-prn]').forEach(tr=>{tr.onclick=()=>openSatellite(tr.dataset.prn);tr.onkeydown=e=>{if(e.key==='Enter')openSatellite(tr.dataset.prn)}})}
function openSatellite(prn){const s=run.satellites.find(x=>x.prn===prn);selected=prn;$('satellite').value=prn;renderChart();$('detail').hidden=false;$('detail-title').textContent=`${prn} · ${s.name}`;$('detail-subtitle').textContent=`NORAD ${s.norad_id||'unconfirmed'} · ${s.orbit_class} · inclination ${fmt(s.inclination_deg)}°`;$('detail-content').innerHTML=`<div class="detail-grid"><div><h3>Residuals & coverage</h3><p>Mean ${fmt(s.mean_km)} km · RMS ${fmt(s.rms_km)} km<br>Maximum ${fmt(s.max_km)} km at ${escapeHTML(s.max_utc||'—')}<br>${s.valid_epochs} / ${s.total_epochs} paired epochs (${fmt(s.coverage_percent,1)}%)<br>RTN RMS: ${(s.rtn_rms_km||[]).map(x=>fmt(x)).join(' / ')||'—'} km<br>Maximum GP age ${fmt(s.max_gp_age_hours)} h</p><h3>GP-age growth (descriptive)</h3><p>${s.age_trend?fmt(s.age_trend.slope_km_per_hour,4)+' km / hour; mixed sets may confound trend':'Insufficient age variation for a fit'}</p><pre>${escapeHTML(JSON.stringify(s.age_bins||[],null,2))}</pre></div><div><h3>Quality & anomaly flags</h3><ul>${(s.reasons.length?s.reasons:['Within configured limits']).map(r=>`<li>${escapeHTML(r.replaceAll('_',' '))}</li>`).join('')}</ul><h3>Configured ${escapeHTML(s.orbit_class)} limits</h3><p>RMS ${s.thresholds.rms_km} km · maximum ${s.thresholds.max_km} km · jump ${s.thresholds.jump_km} km<br>${escapeHTML(run.config.threshold_calibration)}</p><h3>Identity evidence</h3><p>${s.confirmed?'Geometrically confirmed at multiple physical epochs':'No unambiguous geometric match'}<br>Runner-up margin: ${fmt(s.margin_km)} km<br>Review identity.json for every candidate and test epoch.</p><button class="text-button" id="identity-detail">View identity evidence ↗</button></div></div>`;$('identity-detail').onclick=()=>showDialog(`${prn} identity evidence`,s.candidates||[])}
function renderQuality(){const i=run.manifest.inputs,notes=run.notes;const entries=[['Broadcast ephemerides',`${run.satellites.length} satellites · ${i.rinex.sha256.slice(0,12)}…`,'RINEX'],['Mean elements',`${i.gp.length} archived snapshot(s) · age checked per epoch`,'OMM'],['Earth orientation & time',`Pinned EOP ${i.eop.sha256.slice(0,8)}… + leap seconds`,'IERS']];$('quality-list').innerHTML=entries.map(([name,note,badge])=>`<div class="quality-item"><span class="quality-dot"></span><div><strong>${name}</strong><p>${escapeHTML(note)}</p></div><small>${badge}</small></div>`).join('')+`<div class="quality-item"><span class="quality-dot pending"></span><div><strong>Assessment limitations</strong><p>${escapeHTML(notes.length+' method and data-quality notes. '+(run.validation?.pass?'GPS/SP3 baseline: '+fmt(run.validation.broadcast_sp3_rms_m)+' m RMS.':'GPS/SP3 baseline pending.'))}</p><button id="notes" class="text-button">Read quality notes ↗</button></div></div>`;$('notes').onclick=()=>showDialog('Data-quality notes',notes.join('\n\n'))}
function renderChart(){const width=1100,height=270,l=54,r=1036,top=17,bottom=228;const svg=$('chart'),empty=$('chart-empty');chartPoints=[];const active=run?run.satellites.filter(s=>selected==='all'||selected===s.prn):[];const groups=active.map(s=>[s,rows.filter(x=>x.prn===s.prn)]);let series=[];if(view==='rtn'){groups.forEach(([s,rr],j)=>['radial_km','along_km','cross_km'].forEach((key,k)=>series.push({label:`${s.prn} ${['R','T','N'][k]}`,key,color:colors[k],dash:j?'4 3':'',data:rr})));}else groups.forEach(([s,rr],j)=>series.push({label:s.prn,key:view==='age'?'gp_age_hours':'separation_km',color:colors[j%colors.length],data:rr}));const values=series.flatMap(s=>s.data.filter(d=>d[s.key]!=null).map(d=>d[s.key]));const hasData=values.length>0;empty.hidden=hasData;$('chart-unit').textContent=view==='age'?'ELEMENT AGE · HOURS':view==='rtn'?'GP − BROADCAST · KM':'SEPARATION · KM';$('legend').innerHTML=series.length?series.map(s=>`<span class="legend-item"><i style="--c:${s.color}"></i>${escapeHTML(s.label)}</span>`).join(''):'<span class="legend-item"><i style="--c:#14a99a"></i>Validated paired epochs</span>';let lo=view==='rtn'?Math.min(0,...values):Math.min(0,...values),hi=Math.max(1,...values);if(hi-lo<1e-6)hi=lo+1;hi+=.08*(hi-lo);if(view==='rtn')lo-=.08*(hi-lo);const start=run?Date.parse(run.day+'T00:00:00Z'):0,end=start+86400000;const x=t=>l+(Date.parse(t)-start)/(end-start)*(r-l),y=v=>bottom-(v-lo)/(hi-lo)*(bottom-top);let markup='';for(let k=0;k<5;k++){const yy=top+(bottom-top)*k/4;markup+=`<line x1="${l}" y1="${yy}" x2="${r}" y2="${yy}" stroke="#e9efec" stroke-dasharray="3 5"/><text x="${l-13}" y="${yy+3}" text-anchor="end" fill="#9cac9f" font-size="9" font-family="monospace">${hasData?fmt(hi-(hi-lo)*k/4,1):''}</text>`}for(let h=0;h<=24;h+=3){const xx=l+(r-l)*h/24;markup+=`<text x="${xx}" y="${bottom+25}" text-anchor="middle" fill="#9cac9f" font-size="9" font-family="monospace">${String(h).padStart(2,'0')}:00</text>`}if(hasData){for(const s of series){let path='',last=null;for(const row of s.data){const val=row[s.key];if(val==null||!Number.isFinite(val)){last=null;continue}const xx=x(row.utc),yy=y(val),t=Date.parse(row.utc);const move=last===null||t-last>run.config.step_seconds*1500;path+=(move?'M':'L')+xx.toFixed(2)+','+yy.toFixed(2);last=t;chartPoints.push({x:xx,y:yy,row,label:s.label,key:s.key})}markup+=`<path d="${path}" fill="none" stroke="${s.color}" stroke-width="1.7" ${s.dash?`stroke-dasharray="${s.dash}"`:''}/>`}if(view==='separation'&&selected!=='all'){const threshold=active[0].thresholds.max_km;if(threshold<=hi){const yy=y(threshold);markup+=`<line x1="${l}" y1="${yy}" x2="${r}" y2="${yy}" stroke="#c6a66d" stroke-dasharray="5 5"/><text x="${r}" y="${yy-5}" text-anchor="end" fill="#b9a078" font-size="9">Review limit ${threshold} km</text>`}}if($('age-overlay').checked&&view!=='age'){const ages=groups.flatMap(([,rr])=>rr.filter(r=>r.gp_age_hours!=null).map(r=>r.gp_age_hours)),amax=Math.max(1,...ages);groups.forEach(([,rr])=>{let p='',last=null;rr.forEach(row=>{if(row.gp_age_hours==null){last=null;return}const t=Date.parse(row.utc);p+=(last===null||t-last>run.config.step_seconds*1500?'M':'L')+x(row.utc).toFixed(2)+','+(bottom-row.gp_age_hours/amax*(bottom-top)).toFixed(2);last=t});markup+=`<path d="${p}" fill="none" stroke="#bb9f72" stroke-width="1" stroke-dasharray="5 4" opacity=".7"/>`});markup+=`<text x="${r+8}" y="${top+4}" fill="#bb9f72" font-size="8">${fmt(amax,1)} h</text>`;$('legend').innerHTML+='<span class="legend-item"><i style="--c:#bb9f72"></i>GP age · right scale</span>'}const flagged=groups.flatMap(([,rr])=>rr.filter(r=>r.separation_km!=null&&r.flags?.some(f=>['discontinuity','separation_threshold','identity_geometry_inconsistent'].includes(f))));for(const row of flagged){const key=view==='rtn'?'along_km':view==='age'?'gp_age_hours':'separation_km';if(row[key]!=null)markup+=`<circle cx="${x(row.utc)}" cy="${y(row[key])}" r="2.8" fill="#c28b56"/>`}}svg.innerHTML=markup;svg.setAttribute('aria-label',hasData?`${view} for ${selected}, ${run.day}, gaps preserved`:'No validated orbit residuals')}
$('chart').addEventListener('mousemove',e=>{if(!chartPoints.length)return;const rect=$('chart').getBoundingClientRect(),xx=(e.clientX-rect.left)*1100/rect.width,yy=(e.clientY-rect.top)*270/rect.height;const nearest=chartPoints.reduce((a,b)=>Math.hypot(b.x-xx,b.y-yy)<Math.hypot(a.x-xx,a.y-yy)?b:a);const r=nearest.row;$('tooltip').textContent=`${nearest.label} · ${r.utc.slice(11,19)} UTC\n${fmt(r[nearest.key],3)} ${view==='age'?'h':'km'} · GP age ${fmt(r.gp_age_hours,2)} h${r.flags.length?' · '+r.flags.join(', '):''}`;$('tooltip').style.left=Math.min(e.clientX-rect.left+12,rect.width-260)+'px';$('tooltip').style.top=Math.max(0,e.clientY-rect.top-55)+'px';$('tooltip').hidden=false});$('chart').addEventListener('mouseleave',()=>$('tooltip').hidden=true);
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('selected',x===b));renderChart()});$('satellite').onchange=e=>{selected=e.target.value;renderChart()};$('status-filter').onchange=renderTable;$('age-overlay').onchange=renderChart;$('dialog-close').onclick=()=>$('dialog').close();$('manifest').onclick=()=>showDialog('Reproducibility manifest',run.manifest);$('close-detail').onclick=()=>$('detail').hidden=true;$('export').onclick=()=>{if(!run)return;const keys=Object.keys(rows[0]||{}),cell=v=>'"'+String(Array.isArray(v)?v.join(';'):v??'').replaceAll('"','""')+'"';download(run.run_id+'-epochs.csv',[keys.map(cell).join(','),...rows.map(r=>keys.map(k=>cell(r[k])).join(','))].join('\n'),'text/csv')};$('import').onclick=()=>$('file').click();$('file').onchange=async e=>{try{const files=await Promise.all([...e.target.files].map(async f=>JSON.parse(await f.text())));const summary=files.find(x=>x.schema_version),epochs=files.find(Array.isArray);if(!summary||!epochs)throw Error('Select both summary.json and epochs.json together.');load(summary,epochs);toast('Run loaded locally. Files stay in this browser.')}catch(e){toast(e.message)}};document.querySelectorAll('nav a').forEach(a=>a.onclick=()=>{document.querySelectorAll('nav a').forEach(x=>x.classList.toggle('active',a===x))});renderChart();
async function readFeed(base){
  const index=JSON.parse(await feedText(base+'latest.json?check='+Date.now()));
  const texts=await Promise.all([index.summary,index.epochs].map(name=>feedText(base+name)));
  if(index.summary_sha256&&index.epochs_sha256){
    const hashes=await Promise.all(texts.map(async text=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text)))].map(b=>b.toString(16).padStart(2,'0')).join('')));
    if(hashes[0]!==index.summary_sha256||hashes[1]!==index.epochs_sha256)throw Error('Data feed hash mismatch; retry after cache refresh');
  }
  const summary=JSON.parse(texts[0]),epochs=JSON.parse(texts[1]);
  if(run?.run_id===summary.run_id)return;
  if(run&&Date.parse(summary.generated_at)<Date.parse(run.generated_at))return;
  fitArtifacts=index.artifacts||{};feedBase=base;load(summary,epochs);
}
async function feedText(url){
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);
  try{const response=await fetch(url,{cache:'no-store',signal:controller.signal});if(!response.ok)throw Error('Data unavailable: HTTP '+response.status);return await response.text()}
  finally{clearTimeout(timer)}
}
async function refreshPublished(){
  if(!run){try{await readFeed('data/')}catch(error){toast('Bundled run could not load: '+error.message)}}
  try{const config=JSON.parse(await feedText('feed.json'));await readFeed(config.base_url)}
  catch(error){if(!run)toast('No run could be loaded: '+error.message)}
}
refreshPublished();setInterval(refreshPublished,30*60*1000);

refreshFresh();setInterval(refreshFresh,30*60*1000);

refreshTracking();setInterval(refreshTracking,30*60*1000);
